// Part: room: schoolhouse cloakroom (interior designer). Inner air x16..19, y2..4, z10..11 (rooms.json box).
// Layout: the two doorway lanes (x17..18 at z10 and z11) stay clear. West column x16: a coat-hook rail of spruce fence
// pegs at head height. East column x19: a boot bench of two spruce stairs (seats, backs to the east wall). One hanging
// lantern at (17,4,10) is the focal light over the lane from the north door.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const LEGEND = {
  s: ["spruce_stairs", { facing: "east", half: "bottom" }],
  f: "spruce_fence",
  L: ["lantern", { hanging: "true" }],
};

export function build(g) {
  // rows run along +z (z10 then z11); columns along +x (x16..19)
  layers(g, [16, 2, 10], LEGEND, [
    ["   s", "   s"],   // y2: boot bench seats
    ["f   ", "f   "],   // y3: coat pegs
    [" L  ", "    "],   // y4: lantern hanging from the ceiling block
  ]);
}

